.social-sim-container {
    padding: 28px;
    background: linear-gradient(135deg, #0f0c29 0%, #1a1a4e 40%, #24243e 70%, #0d2137 100%);
    min-height: 100vh;
    font-family: -apple-system, 'Inter', 'Segoe UI', sans-serif;
    color: #ffffff;
}

.social-sim-header {
    background: rgba(255,255,255,0.07);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 24px;
    padding: 36px 32px 28px;
    text-align: center;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}

.social-sim-header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #a78bfa, #34d399, #60a5fa);
}

.social-sim-header-icon {
    font-size: 2.4rem;
    margin-bottom: 8px;
}

.social-sim-header h1 {
    font-size: 1.6rem;
    font-weight: 700;
    margin: 0 0 6px;
    background: linear-gradient(135deg, #c4b5fd, #6ee7b7);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.social-sim-subtitle {
    font-size: 0.9rem;
    color: rgba(255,255,255,0.72);
    margin: 0;
    letter-spacing: 0.05em;
}

.social-sim-period-counter {
    text-align: center;
    font-size: 1rem;
    color: rgba(255,255,255,0.6);
    margin-bottom: 24px;
    letter-spacing: 0.04em;
}

.social-sim-period-counter span:nth-child(2),
.social-sim-period-counter span:nth-child(4) {
    font-weight: 700;
    color: #c4b5fd;
    font-size: 1.15rem;
}

.social-sim-briefing {
    background: rgba(167,139,250,0.1);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(167,139,250,0.25);
    border-radius: 18px;
    padding: 24px 28px;
    margin-bottom: 28px;
    line-height: 1.65;
}

.social-sim-briefing-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    color: #a78bfa;
    margin-bottom: 10px;
    font-weight: 600;
}

.social-sim-briefing-text {
    font-size: 0.95rem;
    color: rgba(255,255,255,0.85);
}

.social-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}

.social-sim-kpi-card {
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 16px;
    padding: 22px 18px;
    text-align: center;
    transition: background 0.25s ease, transform 0.2s ease;
    position: relative;
    overflow: hidden;
}

.social-sim-kpi-card::after {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
}

.social-sim-kpi-cash::after { background: linear-gradient(90deg, #34d399, #6ee7b7); }
.social-sim-kpi-rep::after { background: linear-gradient(90deg, #a78bfa, #c4b5fd); }
.social-sim-kpi-students::after { background: linear-gradient(90deg, #60a5fa, #93c5fd); }
.social-sim-kpi-partners::after { background: linear-gradient(90deg, #fbbf24, #fcd34d); }
.social-sim-kpi-jobs::after { background: linear-gradient(90deg, #f472b6, #f9a8d4); }

.social-sim-kpi-card:hover {
    background: rgba(255,255,255,0.1);
    transform: translateY(-3px);
}

.social-sim-kpi-label {
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: rgba(255,255,255,0.72);
    margin-bottom: 10px;
}

.social-sim-kpi-value {
    font-size: 1.9rem;
    font-weight: 700;
    color: #ffffff;
}

.social-sim-kpi-cash .social-sim-kpi-value { color: #6ee7b7; }
.social-sim-kpi-rep .social-sim-kpi-value { color: #c4b5fd; }
.social-sim-kpi-students .social-sim-kpi-value { color: #93c5fd; }
.social-sim-kpi-partners .social-sim-kpi-value { color: #fcd34d; }
.social-sim-kpi-jobs .social-sim-kpi-value { color: #f9a8d4; }

.social-sim-controls {
    background: rgba(255,255,255,0.06);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 20px;
    padding: 28px;
    margin-bottom: 28px;
}

.social-sim-controls h3 {
    font-size: 1.1rem;
    font-weight: 600;
    margin: 0 0 6px;
    color: #e0e7ff;
}

.social-sim-alloc-note {
    font-size: 0.82rem;
    color: rgba(255,255,255,0.7);
    margin: 0 0 20px;
}

.social-sim-input-group {
    margin-bottom: 16px;
}

.social-sim-input-group label {
    display: block;
    font-size: 0.8rem;
    color: rgba(255,255,255,0.78);
    margin-bottom: 6px;
    letter-spacing: 0.03em;
}

.social-sim-input-group input[type="number"] {
    width: 100%;
    background: rgba(255,255,255,0.08);
    border: 1px solid rgba(255,255,255,0.18);
    color: #ffffff;
    border-radius: 10px;
    padding: 10px 14px;
    font-size: 1rem;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    -moz-appearance: textfield;
}

.social-sim-input-group input[type="number"]:focus {
    outline: none;
    border-color: #a78bfa;
    box-shadow: 0 0 0 3px rgba(167,139,250,0.2);
}

.social-sim-alloc-total {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    background: rgba(255,255,255,0.04);
    border-radius: 10px;
    margin-bottom: 16px;
    font-size: 0.9rem;
    color: rgba(255,255,255,0.6);
}

.social-sim-alloc-value {
    font-weight: 700;
    font-size: 1.1rem;
    color: #6ee7b7;
}

.social-sim-separator {
    border-top: 1px solid rgba(255,255,255,0.08);
    margin: 20px 0;
}

.social-sim-submit-btn {
    width: 100%;
    padding: 14px;
    border: none;
    border-radius: 12px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    background: linear-gradient(135deg, #7c3aed, #3b82f6);
    color: #ffffff;
    transition: opacity 0.2s ease, transform 0.15s ease;
    margin-bottom: 10px;
}

.social-sim-submit-btn:hover {
    opacity: 0.9;
    transform: translateY(-1px);
}

.social-sim-undo-btn {
    width: 100%;
    padding: 8px;
    border-radius: 10px;
    background: rgba(255,255,255,0.06);
    border: 1px solid rgba(255,255,255,0.12);
    color: rgba(255,255,255,0.5);
    font-size: 0.82rem;
    cursor: pointer;
    transition: background 0.2s ease;
}

.social-sim-undo-btn:hover {
    background: rgba(255,255,255,0.1);
    color: rgba(255,255,255,0.7);
}

.social-sim-history {
    margin-bottom: 28px;
}

.social-sim-container .table {
    background: rgba(255,255,255,0.04);
    border-radius: 14px;
    overflow: hidden;
    color: rgba(255,255,255,0.8);
    border-collapse: separate;
    border-spacing: 0;
}

.social-sim-container .table thead th {
    background: rgba(167,139,250,0.15);
    color: #c4b5fd;
    border: none;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 12px 14px;
}

.social-sim-container .table tbody td {
    border-top: 1px solid rgba(255,255,255,0.05);
    padding: 10px 14px;
    font-size: 0.88rem;
}

.social-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background: rgba(255,255,255,0.02);
}

.social-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
}

.social-sim-chart-box {
    background: rgba(255,255,255,0.05);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid rgba(255,255,255,0.08);
    border-radius: 16px;
    padding: 20px;
    min-height: 260px;
    position: relative;
}

@media (max-width: 768px) {
    .social-sim-container { padding: 16px; }
    .social-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .social-sim-charts { grid-template-columns: 1fr; }
    .social-sim-header { padding: 24px 18px 20px; }
    .social-sim-header h1 { font-size: 1.3rem; }
    .social-sim-kpi-value { font-size: 1.5rem; }
    .social-sim-controls { padding: 20px; }
    .social-sim-briefing { padding: 18px 20px; }
}

@media (prefers-reduced-motion: reduce) {
    .social-sim-kpi-card,
    .social-sim-submit-btn,
    .social-sim-undo-btn,
    .social-sim-input-group input[type="number"] {
        transition: none;
    }
    .social-sim-kpi-card:hover,
    .social-sim-submit-btn:hover {
        transform: none;
    }
}

.social-sim-kpi-mission::after { background: linear-gradient(90deg, #34d399, #a7f3d0); }
.social-sim-kpi-mission .social-sim-kpi-value { color: #6ee7b7; }

[hidden] { display: none !important; }

.ses-panel { margin-bottom: 4px; }

.ses-check-group {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin: 8px 0 4px;
}
.ses-check {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    font-size: 0.86rem;
    color: rgba(255,255,255,0.82);
    line-height: 1.4;
    cursor: pointer;
    padding: 10px 12px;
    background: rgba(255,255,255,0.04);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 10px;
    transition: background 0.2s ease, border-color 0.2s ease;
}
.ses-check:hover { background: rgba(255,255,255,0.07); }
.ses-check input[type="checkbox"] {
    width: 18px;
    height: 18px;
    margin-top: 1px;
    flex-shrink: 0;
    accent-color: #7c3aed;
    cursor: pointer;
}
.ses-check input[type="checkbox"]:focus-visible {
    outline: 2px solid #a78bfa;
    outline-offset: 2px;
}

