(function() {
    'use strict';

    var POT = { g: 600, c: 360, a: 330, p: 120, i: 250 };
    var USAID_CUT = 0.30;
    var BASELINE = [38, 22, 18, 12, 10];

    class FdiTurnaroundAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Social Enterprise — FDI Turnaround';
            this.version = '2.1.0';
            this.ROUNDS = [
                { briefKey: 'brief_r1' },
                { briefKey: 'brief_r2' },
                { briefKey: 'brief_r3' },
                { briefKey: 'brief_r4' }
            ];
        }

        _clamp(x, a, b) { return Math.max(a, Math.min(b, x)); }
        _emph(x) { return 0.30 + 1.30 * x; }

        _shares(period, dec) {
            var m;
            if (period >= 4 && dec && dec.mix4) m = dec.mix4;
            else if (period >= 2 && dec && dec.mix) m = dec.mix;
            else m = BASELINE;
            var t = m.reduce(function(a, b) { return a + b; }, 0) || 1;
            return m.map(function(x) { return x / t; });
        }

        _lang(){try{if(window.vcI18n&&vcI18n.lang)return String(vcI18n.lang).substring(0,2)==='es'?'es':'en';}catch(e){}var l=(window.mySimulation&&(window.mySimulation.currentLanguage||window.mySimulation.language))||(document.documentElement&&document.documentElement.lang)||'en';return String(l).substring(0,2)==='es'?'es':'en';}
        _scoreAxes(finalCash, finalRep, finalMission, totalPlacements, dec){dec=dec||{};var cashScore=this._clamp(finalCash/700*100,0,100);var sh4=this._shares(4,dec);var maxs=Math.max.apply(null,sh4);var divScore=maxs<=0.40?this._clamp((0.30-maxs)/0.10*40+60,0,100):25;var gov=dec.governance?100:50,ef=dec.emergencyFund?100:55;var sustain=0.55*cashScore+0.20*divScore+0.15*gov+0.10*ef;var placeScore=this._clamp(totalPlacements/340*100,0,100);var rigor=dec.rigor?100:55;var cohort=this._clamp(((dec.studentsKept||580)-200)/380*100,0,100);var impact=0.28*placeScore+0.25*finalMission+0.22*finalRep+0.13*rigor+0.12*cohort;if(finalRep<35)impact=Math.min(impact,50);if(finalMission<50)impact=Math.min(impact,55);var performance='Needs Improvement';if(sustain>=45&&impact>=45)performance='Good';if(sustain>=60&&impact>=60)performance='Excellent';if(sustain>=75&&impact>=75)performance='Outstanding';return {sustain:sustain,impact:impact,overall:Math.min(sustain,impact),performance:performance};}
        formatCompletionMessage(summary){var es=this._lang()==='es';var ov=(summary&&typeof summary.overallScore==='number')?summary.overallScore:Math.round(((summary.sustainabilityScore||0)+(summary.impactScore||0))/2);var perf=(summary&&summary.performance)||'';var tierMap=es?{'Needs Improvement':'Necesita Mejorar','Good':'Buena','Excellent':'Excelente','Outstanding':'Sobresaliente'}:{};var perfL=tierMap[perf]||perf;var sus=summary.sustainabilityScore||0,imp=summary.impactScore||0;var ins=(summary&&summary.insights)||[];var color=ov>=75?'#2e7d32':(ov>=60?'#43a047':(ov>=45?'#f9a825':'#c62828'));var susL=es?'Sostenibilidad':'Sustainability',impL=es?'Impacto':'Impact';var thanks=es?'Gracias por participar.':'Thank you for participating.';var items=ins.map(function(t){return '<li>'+t+'</li>';}).join('');var insBlock=items?('<ul style="text-align:left;margin-top:12px;display:inline-block;">'+items+'</ul>'):'';return '<div class="completion-message text-center p-4">'+'<div style="font-size:2.6rem;font-weight:800;color:'+color+';">'+ov+'/100</div>'+'<p style="font-weight:600;color:'+color+';margin:2px 0;">'+perfL+'</p>'+'<p class="text-muted" style="margin-bottom:6px;">'+susL+': '+sus+' · '+impL+': '+imp+'</p>'+insBlock+'<hr class="my-3"><p class="text-muted">'+thanks+'</p></div>';}
        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 400,
                    reputation: 55,
                    mission: 90,
                    students: 580,
                    corporatePartners: 3,
                    totalPlacements: 0,
                    mfLost: false,
                    baseByPeriod: {},
                    cashHistory: [],
                    reputationHistory: [],
                    missionHistory: [],
                    placementsHistory: [],
                    revenueHistory: [],
                    costHistory: []
                };
            }
            if (!state.domainState.baseByPeriod) state.domainState.baseByPeriod = {};
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    studentsKept: 580, honest: false,
                    mix: [24, 22, 20, 18, 16], paidBootcamp: 40, guardrail: 65,
                    retainMF: true, transparent: true, governance: true,
                    mix4: [22, 22, 20, 20, 16], emergencyFund: true, rigor: true
                };
            }
            this._updatePanels(state.currentPeriod || 1);
            this._updateBriefing(state);
            this._updateAllocDisplays();
        }

        validateDecisions(decisions) {
            var sim = window.mySimulation;
            var period = sim.state.currentPeriod;
            function val(id) { var e = document.getElementById(id); return e ? e.value : null; }
            function num(id, def) { var v = val(id); return v != null ? (parseInt(v) || 0) : def; }
            function chk(id) { var e = document.getElementById(id); return e ? !!e.checked : false; }
            function warn(k) { sim.uiManager.showNotification(sim.t(k), 'warning'); }
            var self = this;

            if (period === 1) {
                decisions.studentsKept = num('studentsInput', 580);
                decisions.honest = chk('honestInput');
                if (decisions.studentsKept < 200 || decisions.studentsKept > 580) { warn('students_warning'); return false; }
            } else if (period === 2) {
                var m = [num('mixGrants', 0), num('mixCorp', 0), num('mixAlianza', 0), num('mixPlace', 0), num('mixIndiv', 0)];
                if (m.reduce(function(a, b) { return a + b; }, 0) !== 100) { warn('alloc_warning'); return false; }
                decisions.mix = m;
                decisions.paidBootcamp = self._clamp(num('bootcampInput', 0), 0, 100);
                decisions.guardrail = self._clamp(num('guardrailInput', 70), 40, 90);
            } else if (period === 3) {
                decisions.retainMF = chk('retainMFInput');
                decisions.transparent = chk('transparentInput');
                decisions.governance = chk('governanceInput');
            } else if (period === 4) {
                var m4 = [num('mix4Grants', 0), num('mix4Corp', 0), num('mix4Alianza', 0), num('mix4Place', 0), num('mix4Indiv', 0)];
                if (m4.reduce(function(a, b) { return a + b; }, 0) !== 100) { warn('alloc_warning'); return false; }
                decisions.mix4 = m4;
                decisions.emergencyFund = chk('emergencyFundInput');
                decisions.rigor = chk('rigorInput');
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var idx = period - 1;

            if (!ds.baseByPeriod) ds.baseByPeriod = {};
            var pk = String(period);
            if (!ds.baseByPeriod[pk]) {
                ds.baseByPeriod[pk] = {
                    cash: ds.cash, rep: ds.reputation, mission: ds.mission,
                    partners: ds.corporatePartners, placements: ds.totalPlacements, mfLost: ds.mfLost
                };
            }
            var base = ds.baseByPeriod[pk];

            var students = (d.studentsKept != null) ? d.studentsKept : 580;
            var sh = this._shares(period, d);
            var honest = !!d.honest;
            var cred = base.rep;

            var mfLost = base.mfLost || (period >= 3 && !d.retainMF);
            var rate = d.retainMF ? 0.60 : (mfLost ? 0.42 : 0.52);
            var placementsQ = Math.round(students * rate * 0.25);

            var grants = POT.g * this._emph(sh[0]) * (cred / 55) * USAID_CUT;
            if (d.governance && period >= 3) grants += 150;                          // Fundación Bolívar renews
            var corp = POT.c * this._emph(sh[1]) * (base.rep / 55) * (1 + 0.08 * base.partners);
            var alianza = POT.a * this._emph(sh[2]);
            var place = (POT.p + 0.9 * placementsQ) * this._emph(sh[3]);
            var indiv = POT.i * this._emph(sh[4]) * (base.rep / 55);

            var intensity = d.paidBootcamp || 0;                                     // Bancolombia paid bootcamp
            var paid = 4.5 * intensity;
            var mission = this._clamp(90 - 0.5 * intensity, 0, 100);
            var guardrail = (d.guardrail != null) ? d.guardrail : 70;
            var drift = mission < Math.min(guardrail, 70);
            if (drift) { grants *= 0.6; indiv *= 0.6; }                              // social funders flee mission drift

            var scandalRep = 0;
            if (period === 3) {                                                      // Cuestión Pública story resolves
                var tr = !!d.transparent;
                if (honest) { scandalRep = tr ? 4 : -4; }
                else { scandalRep = tr ? -14 : -28; grants *= 0.7; corp *= 0.85; }
            }

            var revenue = grants + corp + alianza + place + indiv + paid;
            var opCost = 200 + 1.45 * students;
            var oneTime = 0;
            if (period === 3 && d.retainMF) oneTime += 40;
            if (period === 3 && d.governance) oneTime += 85;
            if (period === 4 && d.rigor) oneTime += 60;
            var cost = opCost + oneTime;
            var net = revenue - cost;

            var cash = base.cash + net;
            var partners = base.partners + ((sh[1] >= 0.20) ? 1 : 0);
            var placementsTot = base.placements + placementsQ;

            var rd = (net > 0 ? 2 : -5) + (honest ? 3 : -2);
            if (d.governance && period === 3) rd += 4;
            if (d.rigor && period === 4) rd += 5;
            if (drift) rd -= 8;
            if (period >= 3 && mfLost && !d.retainMF) rd -= 4;
            rd += scandalRep;
            var ms = Math.max.apply(null, sh);
            rd += (ms > 0.30 ? -3 : (ms <= 0.25 ? 2 : 0));
            var rep = this._clamp(base.rep + rd, 0, 100);

            ds.cash = cash;
            ds.reputation = rep;
            ds.mission = mission;
            ds.students = students;
            ds.corporatePartners = partners;
            ds.totalPlacements = placementsTot;
            ds.mfLost = mfLost;

            ds.cashHistory = ds.cashHistory.slice(0, idx); ds.cashHistory.push(Math.round(cash));
            ds.reputationHistory = ds.reputationHistory.slice(0, idx); ds.reputationHistory.push(Math.round(rep));
            ds.missionHistory = ds.missionHistory.slice(0, idx); ds.missionHistory.push(Math.round(mission));
            ds.placementsHistory = ds.placementsHistory.slice(0, idx); ds.placementsHistory.push(placementsQ);
            ds.revenueHistory = ds.revenueHistory.slice(0, idx); ds.revenueHistory.push(Math.round(revenue));
            ds.costHistory = ds.costHistory.slice(0, idx); ds.costHistory.push(Math.round(cost));
            var __ax = this._scoreAxes(cash, rep, mission, placementsTot, d);
            var __ov = Math.round(__ax.overall);
            ds.score = __ov;
            ds.performance = { overallScore: __ov, sustainabilityScore: Math.round(__ax.sustain), impactScore: Math.round(__ax.impact), grade: __ax.performance };


            this._scheduleBriefingRefresh();

            return {
                period: period,
                revenue: Math.round(revenue),
                cost: Math.round(cost),
                net: Math.round(net),
                cash: Math.round(cash),
                reputation: Math.round(rep),
                mission: Math.round(mission),
                placementsQ: placementsQ,
                maxShare: ms,
                drift: drift,
                crisisChannel: null,
                overallScore: __ov,
                score: __ov
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash', (v) => 'COP ' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('reputationDisplay', 'domainState.reputation', (v) => Math.round(v) + '/100');
            uiManager.bind('missionDisplay', 'domainState.mission', (v) => Math.round(v) + '%');
            uiManager.bind('studentsDisplay', 'domainState.students');
            uiManager.bind('placementsDisplay', 'domainState.totalPlacements');

            var self = this;
            ['mixGrants', 'mixCorp', 'mixAlianza', 'mixPlace', 'mixIndiv',
             'mix4Grants', 'mix4Corp', 'mix4Alianza', 'mix4Place', 'mix4Indiv'].forEach(function(id) {
                var el = document.getElementById(id);
                if (el) el.addEventListener('input', function() { self._updateAllocDisplays(); });
