        getPerformanceSummary(history) {
            if (!history.length) return {};
            var dec = (window.mySimulation && window.mySimulation.state) ? window.mySimulation.state.decisions : {};
            var last = history[history.length - 1].results || {};
            var finalCash = last.cash || 0, finalRep = last.reputation || 0, finalMission = last.mission || 0;
            var totalPlacements = history.reduce(function(s, r) { return s + (r.results ? r.results.placementsQ || 0 : 0); }, 0);

            var sh4 = this._shares(4, dec); var maxs = Math.max.apply(null, sh4);
            var __ax = this._scoreAxes(finalCash, finalRep, finalMission, totalPlacements, dec);
            var sustain = __ax.sustain, impact = __ax.impact, performance = __ax.performance;

            var __es = this._lang() === 'es';
            var insights = [];
            if (finalCash < 0) insights.push(__es ? 'FDI se quedó sin caja: el recorte de USAID te hundió. Diversifica más allá de un solo financiador y haz crecer los ingresos propios.' : 'FDI ran out of cash — the USAID gap sank you. Diversify away from any single funder and grow self-generated revenue.');
            else if (finalCash > 800) insights.push(__es ? 'Sólida liquidez reconstruida tras el choque de financiación.' : 'Strong runway rebuilt after the funding shock.');
            if (finalMission < 50) insights.push(__es ? 'Deriva de misión: los programas de pago empujaron a los estudiantes de estrato 1-3 por debajo de la mitad. Sobrevivir financieramente abandonando la misión no es una empresa social.' : 'Mission drift: paid programs pushed estrato 1-3 students below half. Financial survival that abandons the mission is not a social enterprise.');
            else if (finalMission >= 70) insights.push(__es ? 'Misión mantenida: seguiste siendo una empresa social mientras arreglabas las finanzas.' : 'Mission held — you stayed a social enterprise while fixing the finances.');
            if (maxs > 0.30) insights.push(__es ? 'Tu mezcla de 2027 aún depende de un solo donante (>30%). La concentración de donantes fue lo que causó esta crisis.' : 'Your 2027 mix still leans on one donor (>30%). Donor concentration is what caused this crisis.');
            else if (maxs <= 0.25) insights.push(__es ? 'Mezcla de 2027 bien diversificada: ningún donante único puede volver a hundir a FDI.' : 'Well-diversified 2027 mix — no single donor can sink FDI again.');
            if (finalRep < 35) insights.push(__es ? 'La credibilidad se derrumbó, probablemente por el escándalo de métricas. La honestidad más una auditoría externa protege la confianza de los financiadores.' : 'Credibility collapsed — most likely the metrics scandal. Honesty plus an external audit protects funder trust.');
            if (dec.governance && dec.rigor) insights.push(__es ? 'La reforma de gobernanza + la medición rigurosa de impacto desbloquean capital de inversión de impacto.' : 'Governance reform + rigorous impact measurement unlock impact-investing capital.');

            return {
                sustainabilityScore: Math.round(sustain),
                impactScore: Math.round(impact),
                performance: performance,
                finalCash: finalCash,
                finalReputation: finalRep,
                finalMission: finalMission,
                totalJobPlacements: totalPlacements,
                insights: insights,
                overallScore: Math.round(__ax.overall),
                score: Math.round(__ax.overall)
            };
        }

